reference_solution:
def largest_histogram_rectangle(heights):
    stack = []; best = 0
    for i, height in enumerate(heights + [0]):
        start = i
        while stack and stack[-1][1] > height:
            index, old = stack.pop(); best = max(best, old * (i-index)); start = index
        stack.append((start, height))
    return best

